__modules["tarmac.object"] = function(...)
--- Safe accessors for DCS objects. Event initiators and targets may already
-- be gone when an event is handled; calling a method on such an object
-- raises an error in DCS. These helpers return nil instead.

local object = {}

local function pack(...)
    return { n = select("#", ...), ... }
end

--- Calls obj:method(...) and returns its results, or nil if obj is missing,
-- has no such method or the call fails.
function object.call(obj, method, ...)
    if obj == nil then
        return nil
    end
    local ok, fn = pcall(function() return obj[method] end)
    if not ok or type(fn) ~= "function" then
        return nil
    end
    local results = pack(pcall(fn, obj, ...))
    if not results[1] then
        return nil
    end
    return unpack(results, 2, results.n)
end

function object.name(obj) return object.call(obj, "getName") end
function object.typeName(obj) return object.call(obj, "getTypeName") end
function object.coalition(obj) return object.call(obj, "getCoalition") end
function object.country(obj) return object.call(obj, "getCountry") end
function object.life(obj) return object.call(obj, "getLife") end
function object.desc(obj) return object.call(obj, "getDesc") end
function object.group(obj) return object.call(obj, "getGroup") end

--- Name of the player controlling the unit, or nil for AI.
function object.playerName(obj)
    local name = object.call(obj, "getPlayerName")
    if name == "" then
        return nil
    end
    return name
end

--- Unit category from the descriptor (Unit.Category.*), or nil.
function object.unitCategory(obj)
    local desc = object.desc(obj)
    return desc and desc.category
end

--- True for airplanes and helicopters.
function object.isAircraft(obj)
    local category = object.unitCategory(obj)
    return category == Unit.Category.AIRPLANE or category == Unit.Category.HELICOPTER
end

--- Name of the unit's group, or nil.
function object.groupName(obj)
    return object.name(object.group(obj))
end

--- Position as Vec3, or nil.
function object.point(obj)
    local point = object.call(obj, "getPoint")
    if point then
        return point
    end
    local position = object.call(obj, "getPosition")
    return position and position.p
end

--- True if the object still exists in the world.
function object.exists(obj)
    return object.call(obj, "isExist") == true
end

--- Destroys the object if it still exists. Returns true on success.
function object.destroy(obj)
    if not object.exists(obj) then
        return false
    end
    return pcall(obj.destroy, obj)
end

return object
end

-- module tarmac.scheduler (tarmac/scheduler.lua)
__modules["tarmac.scheduler"] = function(...)
--- Error-safe wrapper around timer.scheduleFunction.
--   scheduler.after(5, fn, a, b)        run fn(a, b) once in 5 seconds
--   local task = scheduler.every(60, fn) run fn every 60 seconds
--   task:cancel()
-- A repeating function stops when it returns false. Errors are logged with
-- a traceback and do not stop a repeating task.

local Log = require("tarmac.log")

local log = Log.new("tarmac.scheduler")

local scheduler = {}

local Task = {}
Task.__index = Task

function Task:cancel()
    self.cancelled = true
    if self.id then
        pcall(timer.removeFunction, self.id)
        self.id = nil
    end
end

local function run(task)
    local ok, result = xpcall(function()
        return task.fn(unpack(task.args, 1, task.args.n))
    end, function(err)
        return debug and debug.traceback and debug.traceback(tostring(err), 2) or tostring(err)
    end)
    if not ok then
        log:error("task '%s' failed: %s", task.name, result)
    end
    return ok, result
end

local function newTask(fn, name, ...)
    return setmetatable({ fn = fn, name = name or tostring(fn), args = { n = select("#", ...), ... } }, Task)
end

--- Runs fn(...) once after delay seconds. Returns a task that can be cancelled.
function scheduler.after(delay, fn, ...)
    local task = newTask(fn, nil, ...)
    task.id = timer.scheduleFunction(function()
        task.id = nil
        if not task.cancelled then
            run(task)
        end
        return nil
    end, nil, timer.getTime() + math.max(delay, 0))
    return task
end

--- Runs fn() every interval seconds. Options:
--   delay  seconds until the first run (default: interval)
--   name   used in error messages
function scheduler.every(interval, fn, options)
    options = options or {}
    local task = newTask(fn, options.name)
    task.interval = interval
    task.id = timer.scheduleFunction(function(_, time)
        if task.cancelled then
            return nil
        end
        local ok, result = run(task)
        if task.cancelled or (ok and result == false) then
            task.id = nil
            return nil
        end
        return time + task.interval
    end, nil, timer.getTime() + math.max(options.delay or interval, 0))
    return task
end

return scheduler
end

-- module tarmac.events (tarmac/events.lua)
__modules["tarmac.events"] = function(...)
--- Event bus on top of world.addEventHandler.
--   events.on("UNIT_LOST", function(event) ... end)
--   events.on(world.event.S_EVENT_BIRTH, fn)
-- Names without the S_EVENT_ prefix are accepted. Names that are not DCS
-- events are custom events, raised with events.emit(name, payload).
-- Every handler runs protected: an error is logged and the other handlers
-- still receive the event.

local Log = require("tarmac.log")

local log = Log.new("tarmac.events")

local events = {}

local subscribers = {}
local registered = false

local function resolve(name)
    if type(name) == "number" then
        return name
    end
    if type(name) ~= "string" then
        error("event name expected, got " .. type(name), 3)
    end
    return world.event[name] or world.event["S_EVENT_" .. name] or name
end

local function dispatch(key, payload)
    local list = subscribers[key]
    if list == nil then
        return
    end
    -- iterate over a snapshot, handlers may subscribe or unsubscribe
    local snapshot = {}
    for i = 1, #list do
        snapshot[i] = list[i]
    end
    for i = 1, #snapshot do
        local subscription = snapshot[i]
        if not subscription.removed then
            local ok, err = xpcall(function()
                subscription.fn(payload)
            end, function(e)
                return debug and debug.traceback and debug.traceback(tostring(e), 2) or tostring(e)
            end)
            if not ok then
                local name = type(key) == "number" and events.nameOf(key) or tostring(key)
                log:error("handler for event %s failed: %s", name, err)
            end
        end
    end
end

local handler = {}

function handler:onEvent(event)
    if event ~= nil and event.id ~= nil then
        dispatch(event.id, event)
    end
end

--- Subscribes fn to an event. Returns a subscription for events.off.
function events.on(name, fn)
    local key = resolve(name)
    if type(key) == "number" and not registered then
        world.addEventHandler(handler)
        registered = true
    end
    local subscription = { key = key, fn = fn }
    subscribers[key] = subscribers[key] or {}
    table.insert(subscribers[key], subscription)
    return subscription
end

function events.off(subscription)
    local list = subscribers[subscription.key]
    if list == nil then
        return
    end
    subscription.removed = true
    for i = #list, 1, -1 do
        if list[i] == subscription then
            table.remove(list, i)
        end
    end
end

--- Raises a custom event (or replays a DCS event) to all subscribers.
function events.emit(name, payload)
    dispatch(resolve(name), payload)
end

--- Name of a DCS event id ("UNIT_LOST"), for logging.
function events.nameOf(id)
    for name, value in pairs(world.event) do
        if value == id then
            return (name:gsub("^S_EVENT_", ""))
        end
    end
    return tostring(id)
end

return events
end

-- module tarmac.db (tarmac/db.lua)
__modules["tarmac.db"] = function(...)
--- Template database: every group, unit, static and trigger zone of the
-- mission, read once from env.mission when Tarmac loads. Records stay
-- available after the objects have died, which makes them the source for
-- respawning groups exactly as they were placed in the mission editor.
-- Groups spawned at runtime through tarmac.spawn are registered as well;
-- units that appear without a record (dynamic slots, other scripts) are
-- added from their live object by the tracker.
--
-- Group record: { name, category = "plane"|"helicopter"|"vehicle"|"ship"|"static",
--                 coalition, countryId, source = "mission"|"runtime"|"live", data }
-- Unit record:  { name, groupName, type, skill, coalition, category, countryId, index }
-- Zone record:  { name, point = Vec3, radius, vertices, properties }

local Log = require("tarmac.log")
local util = require("tarmac.util")

local log = Log.new("tarmac.db")

local db = {}

local groups, units, zones = {}, {}, {}

local categoryKeys = { "plane", "helicopter", "vehicle", "ship", "static" }
local coalitionKeys = { red = 1, blue = 2, neutrals = 0, neutral = 0 }

-- Old mission formats store names as dictionary keys.
local function text(value)
    if type(value) == "string" and value:find("^DictKey_") and env.getValueDictByKey then
        return env.getValueDictByKey(value)
    end
    return value
end

--- Adds (or replaces) a group record. data is the group table in mission
-- editor format; it is copied.
function db.addGroup(data, meta)
    local name = text(data.name)
    local record = {
        name = name,
        category = meta.category,
        coalition = meta.coalition,
        countryId = meta.countryId,
        source = meta.source or "runtime",
        data = util.deepCopy(data),
    }
    record.data.name = name
    local previous = groups[name]
    if previous then
        for _, unitData in ipairs(previous.data.units or {}) do
            if units[unitData.name] and units[unitData.name].groupName == name then
                units[unitData.name] = nil
            end
        end
    end
    groups[name] = record
    for index, unitData in ipairs(record.data.units or {}) do
        unitData.name = text(unitData.name)
        units[unitData.name] = {
            name = unitData.name,
            groupName = name,
            type = unitData.type,
            skill = unitData.skill,
            coalition = record.coalition,
            category = record.category,
            countryId = record.countryId,
            index = index,
        }
    end
    return record
end

--- Registers a unit seen in the world without a record (e.g. a dynamic
-- slot). Returns its unit record.
function db.addLiveUnit(info)
    local record = units[info.name]
    if record then
        return record
    end
    local group = groups[info.groupName]
    if group == nil then
        group = {
            name = info.groupName,
            category = info.category,
            coalition = info.coalition,
            countryId = info.countryId,
            source = "live",
            data = { name = info.groupName, units = {} },
        }
        groups[info.groupName] = group
    end
    local units_ = group.data.units
    units_[#units_ + 1] = { name = info.name, type = info.type }
    record = {
        name = info.name,
        groupName = info.groupName,
        type = info.type,
        coalition = info.coalition,
        category = info.category,
        countryId = info.countryId,
        index = #units_,
    }
    units[info.name] = record
    return record
end

local function loadZones(mission)
    local list = mission.triggers and mission.triggers.zones or {}
    for _, zoneData in pairs(list) do
        local properties = {}
        for _, property in pairs(zoneData.properties or {}) do
            if property.key then
                properties[property.key] = property.value
            end
        end
        local name = text(zoneData.name)
        zones[name] = {
            name = name,
            point = { x = zoneData.x, y = 0, z = zoneData.y },
            radius = zoneData.radius,
            vertices = zoneData.verticies,
            properties = properties,
        }
    end
end

--- Reads a mission table (env.mission). Called automatically on load.
function db.load(mission)
    groups, units, zones = {}, {}, {}
    if mission == nil then
        log:warn("no mission data available")
        return
    end
    local count = 0
    for coalitionKey, coalitionData in pairs(mission.coalition or {}) do
        local coalitionId = coalitionKeys[coalitionKey]
        for _, countryData in pairs(coalitionData.country or {}) do
            for _, category in ipairs(categoryKeys) do
                local categoryData = countryData[category]
                for _, groupData in pairs(categoryData and categoryData.group or {}) do
                    db.addGroup(groupData, {
                        category = category,
                        coalition = coalitionId,
                        countryId = countryData.id,
                        source = "mission",
                    })
                    count = count + 1
                end
            end
        end
    end
    loadZones(mission)
    log:info("loaded %d groups, %d units and %d zones", count, util.count(units), util.count(zones))
end

--- Group record by name, or nil. Do not modify the returned record.
function db.group(name)
    return groups[name]
end

--- Unit record by unit name, or nil.
function db.unit(name)
    return units[name]
end

--- Zone record by name, or nil.
function db.zone(name)
    return zones[name]
end

--- Copy of a group's mission editor data, ready to be modified and spawned.
function db.groupData(name)
    local record = groups[name]
    return record and util.deepCopy(record.data)
end

--- Copy of a group's route points, or nil.
function db.route(name)
    local record = groups[name]
    local route = record and record.data.route
    return route and route.points and util.deepCopy(route.points)
end

--- Group records matching a filter, sorted by name. Filter fields (all
-- optional): prefix, category, coalition, source.
function db.findGroups(filter)
    filter = filter or {}
    local list = {}
    for name, record in pairs(groups) do
        if (filter.prefix == nil or util.startsWith(name, filter.prefix))
                and (filter.category == nil or record.category == filter.category)
                and (filter.coalition == nil or record.coalition == filter.coalition)
                and (filter.source == nil or record.source == filter.source) then
            list[#list + 1] = record
        end
    end
    table.sort(list, function(a, b) return a.name < b.name end)
    return list
end

--- True if the unit is a client or player slot.
function db.isClientUnit(name)
    local record = units[name]
    return record ~= nil and (record.skill == "Client" or record.skill == "Player")
end

db.load(env.mission)

return db
end

-- module tarmac.tracker (tarmac/tracker.lua)
__modules["tarmac.tracker"] = function(...)
--- Keeps track of the living units of every group, driven by events.
-- DCS removes dead objects quickly and Object.destroy raises no events at
-- all, so asking the world "is this group dead?" is unreliable at the
-- moment a unit dies. The tracker answers it from its own bookkeeping:
--   tracker.aliveCount("RedCAP-1")
-- and raises the custom event "tarmac.groupDead" ({ groupName = ... }) once
-- when the last tracked unit of a group is lost.

local Log = require("tarmac.log")
local db = require("tarmac.db")
local events = require("tarmac.events")
local object = require("tarmac.object")

local log = Log.new("tarmac.tracker")

local tracker = {}

local alive = {}   -- [groupName] = { [unitName] = true }
local counts = {}  -- [groupName] = number of living units
local groupOf = {} -- [unitName] = groupName

--- Records a living unit.
function tracker.unitAlive(unitName, groupName)
    if groupOf[unitName] == groupName and alive[groupName] and alive[groupName][unitName] then
        return
    end
    if groupOf[unitName] and groupOf[unitName] ~= groupName then
        tracker.unitLost(unitName, true)
    end
    alive[groupName] = alive[groupName] or {}
    alive[groupName][unitName] = true
    counts[groupName] = (counts[groupName] or 0) + 1
    groupOf[unitName] = groupName
end

--- Records the loss of a unit. Returns the group name and the number of
-- units left. Repeated reports for the same unit are ignored.
function tracker.unitLost(unitName, silent)
    local groupName = groupOf[unitName]
    if groupName == nil or not (alive[groupName] and alive[groupName][unitName]) then
        return groupName, groupName and counts[groupName] or 0
    end
    alive[groupName][unitName] = nil
    counts[groupName] = counts[groupName] - 1
    local left = counts[groupName]
    if left == 0 and not silent then
        log:debug("group %s has no living units left", groupName)
        events.emit("tarmac.groupDead", { groupName = groupName, lastUnit = unitName })
    end
    return groupName, left
end

--- Forgets all units of a group, e.g. right before it is respawned.
function tracker.reset(groupName)
    for unitName in pairs(alive[groupName] or {}) do
        groupOf[unitName] = nil
    end
    alive[groupName] = nil
    counts[groupName] = 0
end

--- Number of living units of a group.
function tracker.aliveCount(groupName)
    return counts[groupName] or 0
end

--- Names of the living units of a group, sorted.
function tracker.aliveUnits(groupName)
    local list = {}
    for unitName in pairs(alive[groupName] or {}) do
        list[#list + 1] = unitName
    end
    table.sort(list)
    return list
end

--- True when the group is gone from the world (or has no units left
-- there). Wrecks still falling from the sky count as present.
function tracker.isGone(groupName)
    local group = Group.getByName(groupName)
    if group == nil or not object.exists(group) then
        return true
    end
    local size = object.call(group, "getSize")
    return size == nil or size == 0
end

--- Records all units of a live group object (after spawning or seeding).
function tracker.trackGroup(group)
    local groupName = object.name(group)
    if groupName == nil then
        return
    end
    for _, unit in ipairs(object.call(group, "getUnits") or {}) do
        local unitName = object.name(unit)
        if unitName then
            tracker.unitAlive(unitName, groupName)
        end
    end
end

--- Destroys a unit and records its loss, because Object.destroy raises no
-- events in DCS.
function tracker.destroyUnit(unit)
    local unitName = object.name(unit)
    object.destroy(unit)
    if unitName then
        tracker.unitLost(unitName)
    end
end

--- Destroys a whole group and records the loss of all its units.
function tracker.destroyGroup(groupName)
    local group = Group.getByName(groupName)
    if group then
        object.destroy(group)
    end
    for _, unitName in ipairs(tracker.aliveUnits(groupName)) do
        tracker.unitLost(unitName)
    end
end

local function registerUnknown(unit, unitName)
    local group = object.group(unit)
    local groupName = object.name(group)
    if groupName == nil then
        return nil
    end
    local categoryKeys = {
        [Unit.Category.AIRPLANE] = "plane",
        [Unit.Category.HELICOPTER] = "helicopter",
        [Unit.Category.GROUND_UNIT] = "vehicle",
        [Unit.Category.SHIP] = "ship",
    }
    return db.addLiveUnit({
        name = unitName,
        groupName = groupName,
        type = object.typeName(unit),
        coalition = object.coalition(unit),
        countryId = object.country(unit),
        category = categoryKeys[object.unitCategory(unit)],
    })
end

local function onBirth(event)
    local unit = event.initiator
    local unitName = object.name(unit)
    -- only units belong to groups; statics, weapons and scenery do not
    if unitName == nil or object.group(unit) == nil then
        return
    end
    local record = db.unit(unitName) or registerUnknown(unit, unitName)
    if record and record.category ~= "static" then
        tracker.unitAlive(unitName, record.groupName)
    end
end

local function onLoss(event)
    local unitName = object.name(event.initiator)
    if unitName and groupOf[unitName] then
        tracker.unitLost(unitName)
    end
end

-- Units that already exist when Tarmac is loaded (no birth events seen).
local function seed()
    for _, record in ipairs(db.findGroups({ source = "mission" })) do
        if record.category ~= "static" then
            local group = Group.getByName(record.name)
            if group then
                tracker.trackGroup(group)
            end
        end
    end
end

events.on("BIRTH", onBirth)
events.on("UNIT_LOST", onLoss)
events.on("DEAD", onLoss)
events.on("CRASH", onLoss)
events.on("PILOT_DEAD", onLoss)
seed()

return tracker
end

-- module tarmac.spawn (tarmac/spawn.lua)
__modules["tarmac.spawn"] = function(...)
--- Spawning groups and statics from mission editor templates.
--   spawn.respawn("RedCAP-1")                      original group, original place
--   spawn.clone("TPL-SAR-Red", { name = "SAR #1", route = points })
--   spawn.add("vehicle", country.id.USA, groupData) any group table
-- Spawned groups are registered in tarmac.db and tarmac.tracker. Every
-- function returns the new Group (or StaticObject), or nil and a message.

local Log = require("tarmac.log")
local util = require("tarmac.util")
local db = require("tarmac.db")
local tracker = require("tarmac.tracker")

local log = Log.new("tarmac.spawn")

local spawn = {}

local groupCategories = {
    plane = Group.Category.AIRPLANE,
    helicopter = Group.Category.HELICOPTER,
    vehicle = Group.Category.GROUND,
    ship = Group.Category.SHIP,
}

local cloneCounter = 0

-- Prepares mission editor data for coalition.addGroup: the group appears
-- immediately and DCS assigns fresh ids.
local function prepare(data, options)
    data.lateActivation = false
    data.start_time = 0
    data.groupId = nil
    for _, unitData in ipairs(data.units or {}) do
        unitData.unitId = nil
    end
    if options.route then
        data.route = data.route or {}
        data.route.points = util.deepCopy(options.route)
    end
    if options.uncontrolled ~= nil then
        data.uncontrolled = options.uncontrolled
    end
    if options.modify then
        options.modify(data)
    end
    return data
end

local function addStatic(countryId, data, meta, register)
    local staticData = util.deepCopy(data.units and data.units[1] or data)
    staticData.dead = false
    staticData.unitId = nil
    if register then
        db.addGroup({ name = data.name or staticData.name, units = { util.deepCopy(staticData) } }, {
            category = "static",
            coalition = meta.coalition,
            countryId = countryId,
            source = "runtime",
        })
    end
    local ok, result = pcall(coalition.addStaticObject, countryId, staticData)
    if not ok or result == nil then
        return nil, "coalition.addStaticObject failed: " .. tostring(result)
    end
    return result
end

local function addGroup(category, countryId, data, coalitionId, register)
    local groupCategory = groupCategories[category]
    if groupCategory == nil then
        return nil, "unknown category " .. tostring(category)
    end
    -- register first: birth events may arrive while addGroup is running
    if register then
        db.addGroup(data, { category = category, coalition = coalitionId, countryId = countryId, source = "runtime" })
    end
    tracker.reset(data.name)
    local ok, group = pcall(coalition.addGroup, countryId, groupCategory, data)
    if not ok or group == nil then
        return nil, "coalition.addGroup failed: " .. tostring(group)
    end
    tracker.trackGroup(group)
    log:debug("spawned %s", data.name)
    return group
end

--- Spawns a group table (mission editor format). category is one of
-- "plane", "helicopter", "vehicle", "ship", "static". meta.coalition is
-- derived from the country when omitted.
function spawn.add(category, countryId, data, meta)
    meta = meta or {}
    local coalitionId = meta.coalition or coalition.getCountryCoalition(countryId)
    if category == "static" then
        return addStatic(countryId, data, { coalition = coalitionId }, true)
    end
    return addGroup(category, countryId, data, coalitionId, true)
end

--- Spawns a group again exactly as placed in the mission editor. A group
-- with the same name that still exists is replaced. The template itself
-- stays unchanged. Options: route, uncontrolled, modify(data).
function spawn.respawn(name, options)
    options = options or {}
    local record = db.group(name)
    if record == nil or record.source == "live" then
        return nil, "no template for group " .. tostring(name)
    end
    local data = prepare(util.deepCopy(record.data), options)
    if record.category == "static" then
        return addStatic(record.countryId, data, { coalition = record.coalition }, false)
    end
    return addGroup(record.category, record.countryId, data, record.coalition, false)
end

--- Spawns a copy of a template group under a new name. Options:
--   name        new group name (default "<template> #<n>")
--   unitName    function(groupName, index) for unit names (default "<group>-<index>")
--   route, uncontrolled, modify(data)   as for spawn.respawn
function spawn.clone(template, options)
    options = options or {}
    local record = db.group(template)
    if record == nil or record.source == "live" then
        return nil, "no template for group " .. tostring(template)
    end
    cloneCounter = cloneCounter + 1
    local data = prepare(util.deepCopy(record.data), options)
    data.name = options.name or string.format("%s #%d", template, cloneCounter)
    for index, unitData in ipairs(data.units or {}) do
        unitData.name = options.unitName and options.unitName(data.name, index)
            or string.format("%s-%d", data.name, index)
    end
    return spawn.add(record.category, record.countryId, data, { coalition = record.coalition })
end

--- Appends a "run script" action to a waypoint. The command string is
-- executed by DCS when the group reaches the waypoint.
function spawn.addWaypointScript(point, command)
    local task = point.task
    if task == nil or task.id ~= "ComboTask" then
        local tasks = {}
        if task ~= nil then
            tasks[1] = task
        end
        task = { id = "ComboTask", params = { tasks = tasks } }
        point.task = task
    end
    task.params = task.params or {}
    task.params.tasks = task.params.tasks or {}
    local tasks = task.params.tasks
    tasks[#tasks + 1] = {
        number = #tasks + 1,
        auto = false,
        id = "WrappedAction",
        enabled = true,
        params = { action = { id = "Script", params = { command = command } } },
    }
    return point
end

return spawn
end

-- module tarmac.marks (tarmac/marks.lua)
__modules["tarmac.marks"] = function(...)
--- F10 map marks with collision free ids. Mark ids are global in DCS and
-- shared with marks placed by players and other scripts, so Tarmac hands
-- out ids from its own range.

local marks = {}

--- First id used by Tarmac. Change before creating marks if it collides
-- with another script.
marks.firstId = 1500000

local lastId = nil

function marks.nextId()
    lastId = (lastId or (marks.firstId - 1)) + 1
    return lastId
end

-- Optional arguments are left out instead of passing nil, the DCS functions
-- are implemented in C and check the types of the arguments they get.

--- Mark visible to one coalition. Options: readOnly (default true), message.
function marks.toCoalition(coalitionId, text, point, options)
    options = options or {}
    local id = marks.nextId()
    if options.message then
        trigger.action.markToCoalition(id, text, point, coalitionId, options.readOnly ~= false, options.message)
    else
        trigger.action.markToCoalition(id, text, point, coalitionId, options.readOnly ~= false)
    end
    return id
end

--- Mark visible to everyone. Options: readOnly (default true), message.
function marks.toAll(text, point, options)
    options = options or {}
    local id = marks.nextId()
    if options.message then
        trigger.action.markToAll(id, text, point, options.readOnly ~= false, options.message)
    else
        trigger.action.markToAll(id, text, point, options.readOnly ~= false)
    end
    return id
end

function marks.remove(id)
    if id ~= nil then
        trigger.action.removeMark(id)
    end
end

return marks
end

-- module tarmac.menu (tarmac/menu.lua)
__modules["tarmac.menu"] = function(...)
--- F10 radio menus for player groups, including dynamic slots. Menus are
-- built when a player unit is born, so groups that do not exist at mission
-- start get them too.
--   menu.forPlayers(function(player)
--       local root = missionCommands.addSubMenuForGroup(player.groupId, "Industry")
--       missionCommands.addCommandForGroup(player.groupId, "Statistics", root, show, player.groupId)
--       return root
--   end)
-- The builder receives { groupId, groupName, unitName, coalition, playerName }
-- and returns the root path it created; the menu is rebuilt (old one removed)
-- on every birth in the group, so menus never show up twice.

local Log = require("tarmac.log")
local events = require("tarmac.events")
local object = require("tarmac.object")

local log = Log.new("tarmac.menu")

local menu = {}

local builders = {}

local function build(entry, unit)
    local group = object.group(unit)
    local groupId = object.call(group, "getID")
    if groupId == nil then
        return
    end
    local player = {
        groupId = groupId,
        groupName = object.name(group),
        unitName = object.name(unit),
        coalition = object.coalition(unit),
        playerName = object.playerName(unit),
    }
    local previous = entry.paths[groupId]
    if previous then
        missionCommands.removeItemForGroup(groupId, previous)
    end
    local ok, path = pcall(entry.builder, player)
    if not ok then
        log:error("menu builder failed for group %s: %s", player.groupName, path)
        return
    end
    entry.paths[groupId] = path
end

--- Registers a menu builder for all player groups (present and future).
function menu.forPlayers(builder)
    local entry = { builder = builder, paths = {} }
    builders[#builders + 1] = entry
    for _, coalitionId in ipairs({ 0, 1, 2 }) do
        for _, unit in ipairs(coalition.getPlayers(coalitionId) or {}) do
            build(entry, unit)
        end
    end
    return entry
end

events.on("BIRTH", function(event)
    local unit = event.initiator
    if object.playerName(unit) == nil then
        return
    end
    for _, entry in ipairs(builders) do
        build(entry, unit)
    end
end)

return menu
end

-- module tarmac (tarmac/init.lua)
__modules["tarmac"] = function(...)
--- DCS Tarmac - a scripting foundation for DCS World missions.
--
-- Loaded on its own (dist/tarmac.lua) it creates the global "tarmac".
-- Bundled into another script it first looks for an already loaded,
-- compatible Tarmac and reuses it, so a mission never runs two copies side
-- by side. Scripts that bundle Tarmac should therefore only ever
-- require("tarmac") and reach the parts through the returned table.

local VERSION = "0.1.0"

local function parseVersion(version)
    local major, minor, patch = tostring(version):match("^(%d+)%.(%d+)%.(%d+)")
    return tonumber(major), tonumber(minor), tonumber(patch)
end

-- An instance can replace this one if it has the same major version (and
-- the same minor version while in 0.x) and is at least as new.
local function compatible(version)
    local major, minor, patch = parseVersion(version)
    local wantMajor, wantMinor, wantPatch = parseVersion(VERSION)
    if major == nil or major ~= wantMajor then
        return false
    end
    if major == 0 and minor ~= wantMinor then
        return false
    end
    if minor ~= wantMinor then
        return minor > wantMinor
    end
    return patch >= wantPatch
end

local existing = rawget(_G, "tarmac")
if type(existing) == "table" and compatible(existing.version) then
    return existing
end
if existing ~= nil then
    env.warning(string.format("[tarmac] loaded Tarmac %s is not compatible with %s, using a private copy",
        tostring(type(existing) == "table" and existing.version), VERSION), false)
end

local tarmac = {
    version = VERSION,
    log = require("tarmac.log"),
    util = require("tarmac.util"),
    side = require("tarmac.side"),
    object = require("tarmac.object"),
    scheduler = require("tarmac.scheduler"),
    events = require("tarmac.events"),
    db = require("tarmac.db"),
    tracker = require("tarmac.tracker"),
    spawn = require("tarmac.spawn"),
    marks = require("tarmac.marks"),
    menu = require("tarmac.menu"),
}

if existing == nil then
    _G.tarmac = tarmac
end

env.info("[tarmac] Tarmac " .. VERSION .. " loaded", false)

return tarmac
end

-- module industry.config (industry/config.lua)
__modules["industry.config"] = function(...)
--- Default configuration and merging of the mission's configuration table.
-- The mission passes one table to industry.setup(); everything not given
-- falls back to the defaults below. Unknown keys are reported in dcs.log,
-- which catches typos early.

local tarmac = require("tarmac")

local log = tarmac.log.new("industry.config")

local config = {}

config.defaults = {
    -- tons of resources each coalition starts with
    startResources = 200,

    tickets = {
        start = 100,
        -- both coalitions lose one ticket every interval seconds
        interval = 60,
        -- flags ticketsLowRed / ticketsLowBlue are set below this value
        low = 20,
        -- seconds between the end of the war and loading the next mission
        winCountdown = 600,
    },

    production = {
        interval = 300,
        perFactory = 30,
        -- added once per cycle on top of all factories
        base = 1,
        -- percent of the factory production added per laboratory
        labBoost = 20,
        storageCapacity = 1000,
    },

    respawn = {
        interval = 60,
        -- respawn is forced after this many loops even if a wreck still exists
        retries = 2,
        -- garbage collection for groups that vanished without events
        deadCheckInterval = 300,
        -- default respawn costs in tons per group category
        costs = { plane = 200, helicopter = 200, vehicle = 50, ship = 400 },
        -- groups that respawn: ["Name"] = cost or { cost = 200 } or {}
        groups = {},
        -- AI aircraft that shut down their engines are removed (parking space)
        despawnLandedAI = true,
        -- damaged AI aircraft of respawn groups that sit on the ground without
        -- moving at two dead checks in a row are removed, so the group respawns
        removeStranded = true,
    },

    logistics = {
        -- group name prefixes; matching groups respawn for free
        convoyPrefix = "Convoy",
        transportPrefix = "Transport",
        -- tons per surviving truck when a convoy reaches its last waypoint
        tonsPerTruck = 100,
        -- unit types counted as trucks; nil uses the DCS attribute "Trucks"
        truckTypes = nil,
        -- tons per transport aircraft that lands and shuts down its engines
        tonsPerTransport = 800,
        -- per group overrides: ["Name"] = { role = "convoy"|"transport", tons = 150 }
        groups = {},
    },

    objectives = {
        prefixes = {
            factory = "Factory",
            laboratory = "Laboratory",
            storage = "Storage",
            hq = "HQ",
            secondary = "Secondary",
        },
        -- tickets lost when an objective is destroyed; storages cost a share
        -- of the remaining tickets, an HQ the given fraction of them
        ticketCosts = { factory = 10, laboratory = 5, secondary = 1, hqFraction = 0.5 },
        -- mark enemy objectives on the F10 map
        markers = true,
    },

    losses = {
        -- tickets lost when a player aircraft is destroyed
        playerTickets = 1,
        -- burning wrecks for destroyed ground vehicles
        vehicleSmoke = true,
    },

    csar = {
        enabled = true,
        -- rescue helicopter template per coalition of the downed pilot; the
        -- template itself may belong to any coalition (usually neutral)
        templates = { red = "TPL-SAR-Red", blue = "TPL-SAR-Blue" },
        -- scenery objects removed around the landing point, in meters
        clearRadius = 50,
        -- tickets lost by the coalition of a player that shoots down a rescue helicopter
        killTickets = 1,
    },
}

-- Tables whose keys are chosen by the mission designer.
local openTables = {
    ["respawn.groups"] = true,
    ["logistics.groups"] = true,
}

local function checkKeys(given, defaults, path)
    for key, value in pairs(given) do
        local keyPath = path and (path .. "." .. tostring(key)) or tostring(key)
        local default = defaults and defaults[key]
        if defaults ~= nil and default == nil and not (path and openTables[path]) then
            -- truckTypes defaults to nil but is a valid key
            if keyPath ~= "logistics.truckTypes" then
                log:warn("unknown configuration key '%s'", keyPath)
            end
        elseif type(value) == "table" and type(default) == "table" and not openTables[keyPath] then
            checkKeys(value, default, keyPath)
        end
    end
end

--- Returns the effective configuration for a mission configuration table.
function config.build(given)
    given = given or {}
    checkKeys(given, config.defaults, nil)
    return tarmac.util.merge(config.defaults, given)
end

return config
end

-- module industry.tickets (industry/tickets.lua)
__modules["industry.tickets"] = function(...)
--- Tickets limit the length of a mission and decide who wins. Both sides
-- lose tickets over time; losses and destroyed objectives cost extra.
-- When one side has no tickets left the side with more tickets wins, a
-- countdown runs and the next mission is loaded.

local tarmac = require("tarmac")

local log = tarmac.log.new("industry.tickets")
local side = tarmac.side

local tickets = {}

local cfg
local count = { [1] = 0, [2] = 0 }
local winner = nil
local countdown = 0
local finished = false

local winFlags = { [0] = "missionWinNeutral", [1] = "missionWinRed", [2] = "missionWinBlue" }
local lowFlags = { [1] = "ticketsLowRed", [2] = "ticketsLowBlue" }

local function announce(duration)
    trigger.action.outText(string.format("Tickets: BLUE %d    RED %d", count[2], count[1]), duration or 10)
end

local function countdownTick()
    if countdown > 10 then
        if countdown % 60 == 0 then
            local minutes = countdown / 60
            if winner == side.NEUTRAL then
                trigger.action.outText(string.format("MISSION DRAW. No winner. RTB. Mission ends in %d minutes", minutes), 10)
            else
                trigger.action.outTextForCoalition(winner,
                    string.format("MISSION ACCOMPLISHED. RTB. Mission ends in %d minutes", minutes), 10)
                trigger.action.outTextForCoalition(side.enemy(winner),
                    string.format("MISSION FAILED. RTB. Mission ends in %d minutes", minutes), 10)
            end
        end
    elseif countdown >= 0 then
        trigger.action.outText(string.format("Mission ends in %d seconds", countdown), 3)
    end

    countdown = countdown - 1
    if countdown < 0 then
        finished = true
        trigger.action.setUserFlag(winFlags[winner], true)
        log:info("mission finished, winner %s", side.name(winner))
        if net and net.load_next_mission then
            net.load_next_mission()
        end
        return false
    end
end

--- Ends the war. Called automatically when tickets run out.
function tickets.declareWinner(coalitionId)
    if winner ~= nil then
        return
    end
    winner = coalitionId
    countdown = cfg.tickets.winCountdown
    log:info("winner: %s", side.name(winner))
    tarmac.scheduler.every(1, countdownTick, { delay = 0, name = "industry.tickets.countdown" })
end

local function evaluate()
    if count[1] <= 0 or count[2] <= 0 then
        if count[1] > count[2] then
            tickets.declareWinner(side.RED)
        elseif count[2] > count[1] then
            tickets.declareWinner(side.BLUE)
        else
            tickets.declareWinner(side.NEUTRAL)
        end
    end
    for coalitionId, flag in pairs(lowFlags) do
        if count[coalitionId] <= cfg.tickets.low then
            trigger.action.setUserFlag(flag, true)
        end
    end
end

--- Removes tickets from a coalition (id or name). reason is logged.
function tickets.reduce(coalitionId, amount, reason)
    local id = side.id(coalitionId)
    if count[id] == nil then
        log:warn("cannot reduce tickets of unknown coalition %s (%s)", coalitionId, reason)
        return
    end
    if winner ~= nil or amount <= 0 then
        return
    end
    count[id] = math.max(count[id] - amount, 0)
    log:info("%s loses %d tickets: %s", side.name(id), amount, reason)
    trigger.action.outText(string.format("Tickets %s: %d (-%d)", side.name(id), count[id], amount), 10)
    evaluate()
    announce()
end

function tickets.get(coalitionId)
    return count[side.id(coalitionId)] or 0
end

--- Coalition id of the winner, or nil while the war goes on.
function tickets.winner()
    return winner
end

function tickets.isFinished()
    return finished
end

local function tick()
    if winner ~= nil then
        return false
    end
    count[1] = math.max(count[1] - 1, 0)
    count[2] = math.max(count[2] - 1, 0)
    evaluate()
    announce()
end

function tickets.setup(configuration)
    cfg = configuration
    count[1] = cfg.tickets.start
    count[2] = cfg.tickets.start
    tarmac.scheduler.every(cfg.tickets.interval, tick, { name = "industry.tickets.tick" })
end

return tickets
end

-- module industry.economy (industry/economy.lua)
__modules["industry.economy"] = function(...)
--- Resources (tons) per coalition. Storages limit how much can be held.

local tarmac = require("tarmac")

local log = tarmac.log.new("industry.economy")
local side = tarmac.side

local economy = {}

local cfg
local resources = { [1] = 0, [2] = 0 }
local storages = { [1] = 0, [2] = 0 }

function economy.capacity(coalitionId)
    return storages[coalitionId] * cfg.production.storageCapacity
end

function economy.resources(coalitionId)
    return resources[side.id(coalitionId)] or 0
end

function economy.storages(coalitionId)
    return storages[side.id(coalitionId)] or 0
end

function economy.setStorages(coalitionId, amount)
    storages[coalitionId] = amount
end

--- Adds tons to a coalition (id or name), limited by storage capacity.
-- Returns the amount actually stored.
function economy.add(coalitionId, tons, reason)
    local id = side.id(coalitionId)
    if resources[id] == nil then
        log:warn("cannot add resources to unknown coalition %s (%s)", coalitionId, reason)
        return 0
    end
    local before = resources[id]
    resources[id] = math.max(resources[id] + tons, 0)
    local capacity = economy.capacity(id)
    if resources[id] > capacity then
        resources[id] = capacity
        trigger.action.outText(string.format("Storages of %s are full", side.name(id)), 3)
    end
    log:info("%s %+d tons (%s), now %d", side.name(id), resources[id] - before, reason, resources[id])
    return resources[id] - before
end

function economy.canAfford(coalitionId, tons)
    return economy.resources(coalitionId) >= tons
end

--- Removes tons if available. Returns true on success.
function economy.spend(coalitionId, tons, reason)
    local id = side.id(coalitionId)
    if not economy.canAfford(id, tons) then
        return false
    end
    resources[id] = resources[id] - tons
    log:info("%s spent %d tons (%s), now %d", side.name(id), tons, reason, resources[id])
    return true
end

--- A storage was destroyed: the resources it held are lost. Resources are
-- spread evenly over all storages that existed before the loss.
function economy.storageLost(coalitionId, storagesBefore)
    if storagesBefore <= 0 then
        return 0
    end
    local lost = math.floor(resources[coalitionId] / storagesBefore)
    resources[coalitionId] = resources[coalitionId] - lost
    storages[coalitionId] = storagesBefore - 1
    return lost
end

function economy.setup(configuration, initialStorages)
    cfg = configuration
    for _, id in ipairs(side.BOTH) do
        resources[id] = cfg.startResources
        storages[id] = initialStorages[id] or 0
    end
end

return economy
end

-- module industry.objectives (industry/objectives.lua)
__modules["industry.objectives"] = function(...)
--- Strategic objectives: static objects whose unit name starts with one of
-- the configured prefixes (Factory, Laboratory, Storage, HQ, Secondary).
-- They are registered once at setup with their coalition, so destruction
-- events can be handled even when the object itself is already gone.

local tarmac = require("tarmac")
local economy = require("industry.economy")
local tickets = require("industry.tickets")

local log = tarmac.log.new("industry.objectives")
local side, util, object = tarmac.side, tarmac.util, tarmac.object

local objectives = {}

local cfg
local registry = {} -- [unitName] = { name, kind, coalition, point, markId, destroyed }

objectives.kinds = { "factory", "laboratory", "storage", "hq", "secondary" }

local flagNames = {
    factory = "Factory", laboratory = "Laboratory", storage = "Storage", hq = "HQ", secondary = "Secondary",
}

local markTexts = {
    factory = "Factory of %s producing resources (secondary target)",
    laboratory = "Laboratory of %s boosting factory production",
    storage = "Storage of %s for resources (primary target)",
    hq = "HQ of %s",
    secondary = "Operative target of %s (optional target)",
}

local smokeDensity = { factory = 0.75, laboratory = 0.5, storage = 0.5, hq = 0.5, secondary = 0.75 }

--- Kind of objective for a static name, or nil.
function objectives.classify(name)
    for _, kind in ipairs(objectives.kinds) do
        if util.startsWith(name, cfg.objectives.prefixes[kind]) then
            return kind
        end
    end
    return nil
end

function objectives.get(name)
    return registry[name]
end

-- Names of the statics of a coalition that still work (life above 1).
local function workingStatics(coalitionId)
    local names = {}
    for _, static in ipairs(coalition.getStaticObjects(coalitionId) or {}) do
        local life = object.life(static)
        if life ~= nil and life > 1 then
            local name = object.name(static)
            if name then
                names[name] = true
            end
        end
    end
    return names
end

--- Number of operational objectives of a kind: not destroyed and not
-- heavily damaged.
function objectives.count(coalitionId, kind)
    local working = workingStatics(coalitionId)
    local n = 0
    for name, entry in pairs(registry) do
        if entry.coalition == coalitionId and entry.kind == kind and not entry.destroyed and working[name] then
            n = n + 1
        end
    end
    return n
end

--- Number of objectives of a kind that have not been destroyed.
function objectives.remaining(coalitionId, kind)
    local n = 0
    for _, entry in pairs(registry) do
        if entry.coalition == coalitionId and entry.kind == kind and not entry.destroyed then
            n = n + 1
        end
    end
    return n
end

local function penalty(entry)
    local costs = cfg.objectives.ticketCosts
    local coalitionId, kind = entry.coalition, entry.kind
    if kind == "storage" then
        local before = objectives.remaining(coalitionId, "storage") + 1
        local share = math.ceil(tickets.get(coalitionId) / before)
        economy.storageLost(coalitionId, before)
        tickets.reduce(coalitionId, share, "storage " .. entry.name .. " destroyed")
        if before - 1 == 0 then
            trigger.action.outText(string.format("All %s storages have been destroyed", side.name(coalitionId)), 10)
        else
            trigger.action.outText(string.format("A %s storage has been destroyed. %d tons resources left",
                side.name(coalitionId), economy.resources(coalitionId)), 10)
        end
    elseif kind == "hq" then
        local amount = math.floor(tickets.get(coalitionId) * costs.hqFraction)
        tickets.reduce(coalitionId, amount, "HQ " .. entry.name .. " destroyed")
    else
        tickets.reduce(coalitionId, costs[kind] or 0, kind .. " " .. entry.name .. " destroyed")
    end
end

local destroyedMessages = {
    factory = "Factory of %s coalition destroyed",
    laboratory = "Laboratory of %s coalition destroyed",
    hq = "HQ of %s coalition destroyed",
    secondary = "Secondary Target of %s coalition destroyed",
}

--- Handles the destruction of an objective (once).
function objectives.destroyed(name)
    local entry = registry[name]
    if entry == nil or entry.destroyed then
        return false
    end
    entry.destroyed = true
    log:info("%s objective %s (%s) destroyed", side.name(entry.coalition), name, entry.kind)

    tarmac.marks.remove(entry.markId)
    if entry.point then
        trigger.action.effectSmokeBig(entry.point, 3, smokeDensity[entry.kind])
    end
    trigger.action.setUserFlag(name .. "_destroyed", true)
    trigger.action.setUserFlag(side.name(entry.coalition) .. flagNames[entry.kind] .. "Destroyed", true)
    if destroyedMessages[entry.kind] then
        trigger.action.outText(string.format(destroyedMessages[entry.kind], side.name(entry.coalition)), 10)
    end
    penalty(entry)
    return true
end

local function onLoss(event)
    local name = object.name(event.initiator)
    if name and registry[name] then
        objectives.destroyed(name)
    end
end

function objectives.setup(configuration)
    cfg = configuration
    local counts = {}
    for _, coalitionId in ipairs(side.BOTH) do
        for _, static in ipairs(coalition.getStaticObjects(coalitionId) or {}) do
            local name = object.name(static)
            local kind = objectives.classify(name)
            if kind then
                local entry = {
                    name = name,
                    kind = kind,
                    coalition = coalitionId,
                    point = object.point(static),
                    destroyed = false,
                }
                if cfg.objectives.markers and entry.point then
                    entry.markId = tarmac.marks.toCoalition(side.enemy(coalitionId),
                        string.format(markTexts[kind], side.name(coalitionId)), entry.point)
                end
                registry[name] = entry
                counts[kind] = (counts[kind] or 0) + 1
            end
        end
    end
    for _, kind in ipairs(objectives.kinds) do
        log:info("%d %s objectives", counts[kind] or 0, kind)
    end
    tarmac.events.on("UNIT_LOST", onLoss)
    tarmac.events.on("DEAD", onLoss)
end

return objectives
end

-- module industry.production (industry/production.lua)
__modules["industry.production"] = function(...)
--- Production cycle: factories produce resources, laboratories boost the
-- production, storages limit what can be kept.

local tarmac = require("tarmac")
local economy = require("industry.economy")
local objectives = require("industry.objectives")

local side = tarmac.side

local production = {}

local cfg
local lastReport = {}

--- Runs one production cycle for both coalitions.
function production.run()
    trigger.action.outText("Industry resources arrived", 5)
    for _, coalitionId in ipairs(side.BOTH) do
        local factories = objectives.count(coalitionId, "factory")
        local labs = objectives.count(coalitionId, "laboratory")
        local storages = objectives.count(coalitionId, "storage")

        local produced = cfg.production.base + cfg.production.perFactory * factories
        local bonus = math.floor(produced * cfg.production.labBoost / 100 * labs)

        economy.setStorages(coalitionId, storages)
        economy.add(coalitionId, produced + bonus, "production")
        lastReport[coalitionId] = { factories = factories, labs = labs, storages = storages }

        trigger.action.outText(string.format("New resources produced %s %d tons + %d labs-bonus",
            side.name(coalitionId), produced, bonus), 10)
    end
end

--- Counts of the last production cycle: { factories, labs, storages }.
function production.report(coalitionId)
    return lastReport[coalitionId] or {
        factories = objectives.count(coalitionId, "factory"),
        labs = objectives.count(coalitionId, "laboratory"),
        storages = objectives.count(coalitionId, "storage"),
    }
end

function production.setup(configuration)
    cfg = configuration
    tarmac.scheduler.every(cfg.production.interval, production.run, { delay = 1, name = "industry.production" })
end

return production
end

-- module industry.queue (industry/queue.lua)
__modules["industry.queue"] = function(...)
--- FIFO queue of named entries. A name can only be queued once at a time.
--   local q = Queue.new()
--   q:push({ name = "RedCAP-1", cost = 200 })
--   local head = q:peek()
--   q:pop()

local Queue = {}
Queue.__index = Queue

function Queue.new()
    return setmetatable({ first = 1, last = 0, items = {}, names = {} }, Queue)
end

--- Appends an entry. Returns false if an entry with that name is queued.
function Queue:push(entry)
    if self.names[entry.name] then
        return false
    end
    self.last = self.last + 1
    self.items[self.last] = entry
    self.names[entry.name] = true
    return true
end

--- First entry without removing it, or nil.
function Queue:peek()
    return self.items[self.first]
end

--- Removes and returns the first entry, or nil.
function Queue:pop()
    local entry = self.items[self.first]
    if entry == nil then
        return nil
    end
    self.items[self.first] = nil
    self.first = self.first + 1
    self.names[entry.name] = nil
    return entry
end

function Queue:contains(name)
    return self.names[name] == true
end

function Queue:size()
    return self.last - self.first + 1
end

--- Names in queue order, for status output.
function Queue:list()
    local list = {}
    for i = self.first, self.last do
        list[#list + 1] = self.items[i].name
    end
    return list
end

return Queue
end

-- module industry.respawn (industry/respawn.lua)
__modules["industry.respawn"] = function(...)
--- Respawning of AI groups for resources.
-- A registered group is queued when its last unit is lost (tarmac tracker).
-- Each coalition has two FIFO queues: one for groups that cost resources
-- and one for free respawns. The paid queue is strictly ordered on purpose:
-- an expensive group at the head waits until it can be paid, otherwise
-- cheap groups would use up all resources and expensive ones never return.
-- A queued group only respawns once DCS has removed it from the world (no
-- respawn of wrecks still falling from the sky); after the configured
-- number of retries the respawn is forced.

local tarmac = require("tarmac")
local Queue = require("industry.queue")
local economy = require("industry.economy")

local log = tarmac.log.new("industry.respawn")
local side, db, tracker, object = tarmac.side, tarmac.db, tarmac.tracker, tarmac.object

local respawn = {}

local cfg
local registered = {} -- [groupName] = cost
local paid = { [1] = Queue.new(), [2] = Queue.new() }
local free = { [1] = Queue.new(), [2] = Queue.new() }
local modifiers = {}

--- Registers a group for automatic respawn. cost is a number, a table
-- { cost = n } or nil for the category default.
function respawn.register(groupName, cost)
    if type(cost) == "table" then
        cost = cost.cost
    end
    local record = db.group(groupName)
    if record == nil then
        log:error("respawn group %s does not exist in the mission", groupName)
        return false
    end
    if cost == nil then
        cost = cfg.respawn.costs[record.category] or 0
    end
    registered[groupName] = cost
    return true
end

function respawn.isRegistered(groupName)
    return registered[groupName] ~= nil
end

function respawn.cost(groupName)
    return registered[groupName]
end

--- Names of all registered groups, sorted.
function respawn.groups()
    local list = {}
    for groupName in pairs(registered) do
        list[#list + 1] = groupName
    end
    table.sort(list)
    return list
end

--- Registers a function(groupName, options) that may adjust the spawn
-- options (e.g. the route) before a group respawns.
function respawn.addModifier(fn)
    modifiers[#modifiers + 1] = fn
end

local function coalitionOf(groupName)
    local record = db.group(groupName)
    return record and record.coalition
end

--- Queues a group. cost defaults to the registered cost; a cost of 0 uses
-- the free queue. Returns true if the group was queued.
function respawn.queue(groupName, cost)
    local coalitionId = coalitionOf(groupName)
    if coalitionId ~= side.RED and coalitionId ~= side.BLUE then
        log:warn("cannot queue %s: unknown coalition", groupName)
        return false
    end
    cost = cost or registered[groupName] or 0
    local queue = cost > 0 and paid[coalitionId] or free[coalitionId]
    if paid[coalitionId]:contains(groupName) or free[coalitionId]:contains(groupName) then
        return false
    end
    queue:push({ name = groupName, cost = cost, tries = 0 })
    log:info("queued %s for %d tons", groupName, cost)
    return true
end

function respawn.queued(coalitionId)
    return { paid = paid[coalitionId]:list(), free = free[coalitionId]:list() }
end

local function spawnGroup(entry)
    local options = {}
    for _, modify in ipairs(modifiers) do
        modify(entry.name, options)
    end
    local group, err = tarmac.spawn.respawn(entry.name, options)
    if group == nil then
        log:error("respawn of %s failed: %s", entry.name, err)
        return false
    end
    trigger.action.setUserFlag(entry.name .. "_respawned", true)
    tarmac.events.emit("industry.respawned", { groupName = entry.name, group = group })
    return true
end

local function runPaid(coalitionId)
    local queue = paid[coalitionId]
    local entry = queue:peek()
    if entry == nil then
        return
    end
    if not tracker.isGone(entry.name) and entry.tries < cfg.respawn.retries then
        entry.tries = entry.tries + 1
        log:info("%s still exists, respawn retry %d", entry.name, entry.tries)
        return
    end
    if not economy.canAfford(coalitionId, entry.cost) then
        return
    end
    queue:pop()
    if spawnGroup(entry) then
        economy.spend(coalitionId, entry.cost, "respawn " .. entry.name)
        trigger.action.outText(string.format("Respawned %s group %s for %d tons of resources",
            side.name(coalitionId), entry.name, entry.cost), 10)
    end
end

local function runFree(coalitionId)
    local entry = free[coalitionId]:pop()
    if entry and spawnGroup(entry) then
        trigger.action.outText(string.format("Respawned %s group %s", side.name(coalitionId), entry.name), 10)
    end
end

--- One respawn cycle: at most one paid and one free group per coalition.
function respawn.run()
    for _, coalitionId in ipairs(side.BOTH) do
        runPaid(coalitionId)
        runFree(coalitionId)
    end
end

--- Queues registered groups that are gone without the tracker noticing,
-- e.g. AI that despawned after an emergency landing.
function respawn.collectDead()
    for groupName in pairs(registered) do
        if tracker.isGone(groupName) then
            if respawn.queue(groupName) then
                log:info("found unhandled dead group %s", groupName)
            end
        end
    end
end

-- A pilot ejected from an aircraft of a respawn group: make sure the
-- aircraft is destroyed so the group can respawn (helicopters that landed
-- damaged would otherwise stay forever).
local function onEjection(event)
    local unit = event.initiator
    local groupName = object.groupName(unit)
    if groupName == nil then
        local record = db.unit(object.name(unit) or "")
        groupName = record and record.groupName
    end
    if groupName and registered[groupName] then
        local point = object.point(unit)
        if point then
            trigger.action.explosion(point, 400)
            log:info("pilot ejected from %s, aircraft destroyed", tostring(object.name(unit)))
        end
    end
end

function respawn.setup(configuration)
    cfg = configuration
    for groupName, cost in pairs(cfg.respawn.groups) do
        respawn.register(groupName, cost)
    end
    tarmac.events.on("tarmac.groupDead", function(event)
        if registered[event.groupName] ~= nil then
            respawn.queue(event.groupName)
        end
    end)
    tarmac.events.on("EJECTION", onEjection)
    tarmac.scheduler.every(cfg.respawn.interval, respawn.run, {
        delay = math.min(35, cfg.respawn.interval), name = "industry.respawn",
    })
    tarmac.scheduler.every(cfg.respawn.deadCheckInterval, respawn.collectDead, {
        delay = cfg.respawn.deadCheckInterval + 4, name = "industry.respawn.collectDead",
    })
end

return respawn
end

-- module industry.logistics (industry/logistics.lua)
__modules["industry.logistics"] = function(...)
--- Deliveries of resources by convoys and air transports.
--
-- Convoys: ground groups named "Convoy..." (or listed with role "convoy").
-- When a convoy reaches the last waypoint of its route, every surviving
-- truck delivers its load. Industry adds the waypoint action itself, at
-- mission start and on every respawn, so the mission editor needs no
-- script. The convoy then respawns for free.
--
-- Transports: aircraft groups named "Transport..." (or role "transport").
-- A transport delivers when it shuts down its engines after landing,
-- unless it landed at an enemy airbase.

local tarmac = require("tarmac")
local economy = require("industry.economy")
local respawn = require("industry.respawn")

local log = tarmac.log.new("industry.logistics")
local side, util, db, object, spawn = tarmac.side, tarmac.util, tarmac.db, tarmac.object, tarmac.spawn

local logistics = {}

local cfg
local roles = {}         -- [groupName] = "convoy" | "transport"
local delivered = {}     -- [groupName] = true once a convoy delivered in its current life
local hooked = {}        -- [groupName] = true when the current convoy has the arrival action
local landedAt = {}      -- [unitName] = coalition of the airbase of the last landing

local function override(groupName)
    return cfg.logistics.groups[groupName] or {}
end

function logistics.role(groupName)
    return roles[groupName]
end

local function arrivalCommand(groupName)
    return string.format("if industry then industry.convoyArrived(%q) end", groupName)
end

--- Route of a convoy with the arrival action at its last waypoint.
function logistics.convoyRoute(groupName)
    local points = db.route(groupName)
    if points == nil or #points == 0 then
        return nil
    end
    spawn.addWaypointScript(points[#points], arrivalCommand(groupName))
    return points
end

-- Gives a convoy that is already in the world its route with the arrival
-- action (convoys placed in the editor, late activated convoys).
local function hookConvoy(groupName)
    local group = Group.getByName(groupName)
    local points = logistics.convoyRoute(groupName)
    if group == nil or points == nil then
        return false
    end
    local controller = object.call(group, "getController")
    if controller == nil then
        return false
    end
    controller:setTask({ id = "Mission", params = { route = { points = points } } })
    hooked[groupName] = true
    return true
end

local function isTruck(unit)
    local types = cfg.logistics.truckTypes
    if types then
        local typeName = object.typeName(unit)
        for _, name in ipairs(types) do
            if typeName == name then
                return true
            end
        end
        return false
    end
    return object.call(unit, "hasAttribute", "Trucks") == true
end

--- Called by the waypoint action when a convoy reaches its destination.
function logistics.convoyArrived(groupName)
    if delivered[groupName] then
        return 0
    end
    local group = Group.getByName(groupName)
    if group == nil then
        log:warn("convoy %s arrived but does not exist", groupName)
        return 0
    end
    delivered[groupName] = true
    local coalitionId = object.coalition(group)
    local perTruck = override(groupName).tons or cfg.logistics.tonsPerTruck
    local trucks = 0
    for _, unit in ipairs(object.call(group, "getUnits") or {}) do
        local life = object.life(unit)
        if isTruck(unit) and life and life > 1 then
            trucks = trucks + 1
        end
    end
    local tons = trucks * perTruck
    trigger.action.outText(string.format("A %s convoy with %d tons of resources arrived at its destination",
        side.name(coalitionId), tons), 5)
    economy.add(coalitionId, tons, "convoy " .. groupName)
    respawn.queue(groupName, 0)
    return tons
end

local function landedAtEnemy(unitName, coalitionId)
    local placeCoalition = landedAt[unitName]
    return placeCoalition ~= nil and placeCoalition ~= coalitionId and placeCoalition ~= side.NEUTRAL
end

--- Called when an AI aircraft shut down its engines. Delivers the cargo of
-- transports. Returns the delivered tons.
function logistics.landed(unit)
    local unitName = object.name(unit)
    local groupName = object.groupName(unit)
    if groupName == nil or roles[groupName] ~= "transport" then
        return 0
    end
    local coalitionId = object.coalition(unit)
    if landedAtEnemy(unitName, coalitionId) then
        log:info("transport %s landed at an enemy airbase, cargo lost", unitName)
        return 0
    end
    local tons = override(groupName).tons or cfg.logistics.tonsPerTransport
    trigger.action.outText(string.format("A %s transport with %d tons of resources arrived at its destination",
        side.name(coalitionId), tons), 5)
    economy.add(coalitionId, tons, "transport " .. groupName)
    return tons
end

local function detectRoles()
    for _, record in ipairs(db.findGroups({ source = "mission" })) do
        local name = record.name
        local role = override(name).role
        if role == nil then
            if util.startsWith(name, cfg.logistics.convoyPrefix) and record.category == "vehicle" then
                role = "convoy"
            elseif util.startsWith(name, cfg.logistics.transportPrefix)
                    and (record.category == "plane" or record.category == "helicopter") then
                role = "transport"
            end
        end
        if role then
            roles[name] = role
            if not respawn.isRegistered(name) then
                respawn.register(name, 0)
            end
        end
    end
end

function logistics.setup(configuration)
    cfg = configuration
    detectRoles()

    for name, role in pairs(roles) do
        if role == "convoy" then
            hookConvoy(name)
        end
    end

    -- respawned convoys get the arrival action with their route
    respawn.addModifier(function(groupName, options)
        if roles[groupName] == "convoy" then
            options.route = logistics.convoyRoute(groupName)
            delivered[groupName] = nil
            hooked[groupName] = true
        end
    end)
    tarmac.events.on("tarmac.groupDead", function(event)
        hooked[event.groupName] = nil
    end)
    -- late activated convoys
    tarmac.events.on("BIRTH", function(event)
        local groupName = object.groupName(event.initiator)
        if groupName and roles[groupName] == "convoy" and not hooked[groupName] then
            hooked[groupName] = true
            tarmac.scheduler.after(1, hookConvoy, groupName)
        end
    end)
    tarmac.events.on("LAND", function(event)
        local unitName = object.name(event.initiator)
        if unitName then
            landedAt[unitName] = event.place and object.coalition(event.place) or nil
        end
    end)
    tarmac.events.on("TAKEOFF", function(event)
        local unitName = object.name(event.initiator)
        if unitName then
            landedAt[unitName] = nil
        end
    end)
end

return logistics
end

-- module industry.airfield (industry/airfield.lua)
__modules["industry.airfield"] = function(...)
--- Landed AI aircraft. When an AI aircraft shuts down its engines on the
-- ground it has finished its mission: transports deliver their cargo, the
-- flag "<unit name>_landed" is set for mission editor triggers and the
-- aircraft is removed, which frees the parking spot and lets the group
-- respawn. DCS also reports an engine shutdown when a damaged aircraft
-- loses its engines in flight; those are left alone, they crash and are
-- handled like any other loss (removing them would cost the shooter the kill).

local tarmac = require("tarmac")
local logistics = require("industry.logistics")

local log = tarmac.log.new("industry.airfield")
local object = tarmac.object

local airfield = {}

local cfg

local function onEngineShutdown(event)
    local unit = event.initiator
    local unitName = object.name(unit)
    if unitName == nil or object.playerName(unit) ~= nil then
        return
    end
    if object.call(unit, "inAir") ~= false then
        log:info("%s lost its engines in flight, ignored", unitName)
        return
    end
    logistics.landed(unit)
    trigger.action.setUserFlag(unitName .. "_landed", true)
    if cfg.respawn.despawnLandedAI then
        log:info("%s shut down its engines, removed", unitName)
        tarmac.tracker.destroyUnit(unit)
    end
end

function airfield.setup(configuration)
    cfg = configuration
    tarmac.events.on("ENGINE_SHUTDOWN", onEngineShutdown)
end

return airfield
end

-- module industry.csar (industry/csar.lua)
__modules["industry.csar"] = function(...)
--- Automatic combat search and rescue. When a pilot lands with the
-- parachute on land, the pilot becomes a soldier on the ground and a
-- rescue helicopter of the pilot's coalition is sent to pick him up.
-- Rescue helicopters are clones of one template group per coalition of the
-- downed pilot (default "TPL-SAR-Red" and "TPL-SAR-Blue"). The template
-- keeps its own coalition, usually neutral, so the clone flies for neither
-- side; tick "uncontrolled" for it. Shooting down a rescue helicopter costs
-- the shooter's coalition tickets.

local tarmac = require("tarmac")
local tickets = require("industry.tickets")

local log = tarmac.log.new("industry.csar")
local side, util, db, object, spawn = tarmac.side, tarmac.util, tarmac.db, tarmac.object, tarmac.spawn

local csar = {}

local cfg
local templates = {}     -- [coalitionId] = template group name
local rescueGroups = {}  -- [groupName] = true for spawned rescue helicopters
local missionCounter = 0
local pilotCounter = 0

local soldierTypes = { [side.RED] = "Infantry AK", [side.BLUE] = "Soldier M4" }

-- Parachutes sometimes report coalition 0 or a bogus country.
local parachuteDefaults = {
    pilot_f15_parachute = { coalition = side.BLUE, country = 2 },
    pilot_su27_parachute = { coalition = side.RED, country = 0 },
}

local function pilotIdentity(unit)
    local name = object.name(unit) or "unknown"
    local typeName = object.typeName(unit)
    local coalitionId = object.coalition(unit)
    local countryId = object.country(unit)
    if coalitionId == nil or coalitionId == 0 or countryId == nil or countryId > 99 then
        local fallback = parachuteDefaults[typeName] or parachuteDefaults[name]
        if fallback == nil then
            log:warn("parachute %s (%s) without coalition, assuming blue", name, tostring(typeName))
            fallback = { coalition = side.BLUE, country = 2 }
        end
        coalitionId, countryId = fallback.coalition, fallback.country
    end
    return coalitionId, countryId
end

local function spawnSoldier(point, coalitionId, countryId)
    pilotCounter = pilotCounter + 1
    local groupName = string.format("DownedPilot-%d", pilotCounter)
    local group, err = spawn.add("vehicle", countryId, {
        name = groupName,
        task = "Ground Nothing",
        x = point.x + 1,
        y = point.y,
        units = {
            {
                name = groupName .. "-1",
                type = soldierTypes[coalitionId] or soldierTypes[side.BLUE],
                skill = "Average",
                x = point.x + 1,
                y = point.y,
                heading = 0.286,
                playerCanDrive = true,
            },
        },
        route = {},
    }, { coalition = coalitionId })
    if group == nil then
        log:error("could not spawn downed pilot: %s", err)
        return nil
    end
    return groupName
end

local function clearLandingZone(point)
    local radius = cfg.csar.clearRadius
    if radius == nil or radius <= 0 then
        return
    end
    local volume = { id = world.VolumeType.SPHERE, params = { point = util.vec3(point), radius = radius } }
    world.searchObjects(Object.Category.SCENERY, volume, function(found)
        object.destroy(found)
        return true
    end)
end

local function rescueWaypoint(landPoint, soldierGroup)
    local command = string.format(
        "local g = Group.getByName(%q) if g and g:isExist() then g:destroy() end", soldierGroup)
    return {
        type = "Turning Point",
        action = "Turning Point",
        x = landPoint.x,
        y = landPoint.y,
        alt = math.random(200, 400),
        alt_type = "BARO",
        speed = math.random(60, 100),
        task = {
            id = "ComboTask",
            params = {
                tasks = {
                    {
                        number = 1, auto = false, enabled = true, id = "Land",
                        params = { point = { x = landPoint.x, y = landPoint.y }, duration = math.random(20, 120), durationFlag = true },
                    },
                    {
                        number = 2, auto = false, enabled = true, id = "WrappedAction",
                        params = { action = { id = "Script", params = { command = command } } },
                    },
                },
            },
        },
    }
end

--- Starts a rescue mission for a pilot that landed at point (Vec2).
function csar.startMission(coalitionId, countryId, point)
    local template = templates[coalitionId]
    if template == nil then
        return nil
    end
    local soldierGroup = spawnSoldier(point, coalitionId, countryId)
    if soldierGroup == nil then
        return nil
    end
    local landPoint = { x = point.x + 12, y = point.y + 10 }
    clearLandingZone(landPoint)

    local route = db.route(template) or {}
    route[#route + 1] = rescueWaypoint(landPoint, soldierGroup)

    missionCounter = missionCounter + 1
    local groupName = string.format("SAR %s #%d", side.label(coalitionId), missionCounter)
    rescueGroups[groupName] = true
    local group, err = spawn.clone(template, { name = groupName, route = route })
    if group == nil then
        log:error("could not spawn rescue helicopter: %s", err)
        return nil
    end
    local controller = object.call(group, "getController")
    if controller then
        controller:setCommand({ id = "Start", params = {} })
    end
    trigger.action.outTextForCoalition(coalitionId,
        string.format("Pilot down, parachute spotted at %s. SAR mission started", util.formatPoint(point, 3)), 10)
    log:info("rescue %s sent for %s", groupName, soldierGroup)
    return groupName, soldierGroup
end

function csar.isRescueGroup(groupName)
    return rescueGroups[groupName] == true
end

local function onParachuteLanded(event)
    local unit = event.initiator
    local coalitionId, countryId = pilotIdentity(unit)
    if templates[coalitionId] == nil then
        return
    end
    local position = object.point(unit)
    if position == nil then
        return
    end
    local point = util.vec2(position)
    local surface = land.getSurfaceType(point)
    object.destroy(unit)
    if surface == land.SurfaceType.LAND or surface == land.SurfaceType.ROAD or surface == land.SurfaceType.RUNWAY then
        csar.startMission(coalitionId, countryId, point)
    end
end

local function targetGroupName(target)
    local name = object.groupName(target)
    if name then
        return name
    end
    local record = db.unit(object.name(target) or "")
    return record and record.groupName
end

local function onKill(event)
    local playerName = object.playerName(event.initiator)
    if playerName == nil or object.unitCategory(event.target) ~= Unit.Category.HELICOPTER then
        return
    end
    local groupName = targetGroupName(event.target)
    if groupName and rescueGroups[groupName] then
        trigger.action.outText(string.format("Player %s shot down SAR unit %s", playerName, groupName), 10)
        tickets.reduce(object.coalition(event.initiator), cfg.csar.killTickets, "rescue helicopter shot down")
    else
        trigger.action.outText(string.format("Player %s shot down %s", playerName, tostring(groupName)), 10)
    end
end

function csar.setup(configuration)
    cfg = configuration
    if not cfg.csar.enabled then
        return
    end
    for _, coalitionId in ipairs(side.BOTH) do
        local name = cfg.csar.templates[side.name(coalitionId)]
        local record = name and db.group(name)
        if record and record.category == "helicopter" then
            templates[coalitionId] = name
            log:info("rescue template for %s pilots: %s", side.name(coalitionId), name)
        elseif name then
            log:info("no rescue helicopter group %s, no rescue missions for %s pilots", name, side.name(coalitionId))
        end
    end
    tarmac.events.on("LANDING_AFTER_EJECTION", onParachuteLanded)
    tarmac.events.on("KILL", onKill)
end

return csar
end

-- module industry.losses (industry/losses.lua)
__modules["industry.losses"] = function(...)
--- Reactions to lost units: destroyed player aircraft cost tickets,
-- destroyed ground vehicles keep burning for a while.

local tarmac = require("tarmac")
local tickets = require("industry.tickets")

local log = tarmac.log.new("industry.losses")
local object, db = tarmac.object, tarmac.db

local losses = {}

local cfg

local function coalitionOf(unit)
    local coalitionId = object.coalition(unit)
    if coalitionId == nil then
        local record = db.unit(object.name(unit) or "")
        coalitionId = record and record.coalition
    end
    return coalitionId
end

local function onUnitLost(event)
    local unit = event.initiator
    local category = object.unitCategory(unit)

    if category == Unit.Category.GROUND_UNIT and cfg.losses.vehicleSmoke then
        local point = object.point(unit)
        if point then
            trigger.action.effectSmokeBig(point, 1, 0.5)
        end
    end

    local playerName = object.playerName(unit)
    if playerName and object.isAircraft(unit) then
        local coalitionId = coalitionOf(unit)
        log:info("player %s (%s) lost", playerName, tostring(object.name(unit)))
        tickets.reduce(coalitionId, cfg.losses.playerTickets, "player " .. playerName .. " lost")
    end
end

function losses.setup(configuration)
    cfg = configuration
    tarmac.events.on("UNIT_LOST", onUnitLost)
end

return losses
end

-- module industry.menu (industry/menu.lua)
__modules["industry.menu"] = function(...)
--- F10 menu "Industry" for every player group, including dynamic slots.

local tarmac = require("tarmac")
local economy = require("industry.economy")
local production = require("industry.production")
local tickets = require("industry.tickets")

local menu = {}

--- Text of the statistics message.
function menu.statistics()
    local blue, red = production.report(2), production.report(1)
    return string.format(
        "BLUE Fact: %2d   Labs: %2d    Stor: %2d    Res: %4d\n" ..
        "RED   Fact: %2d   Labs: %2d    Stor: %2d    Res: %4d\n" ..
        "Tickets: BLUE %d    RED %d",
        blue.factories, blue.labs, blue.storages, economy.resources(2),
        red.factories, red.labs, red.storages, economy.resources(1),
        tickets.get(2), tickets.get(1))
end

local function showStatistics(groupId)
    trigger.action.outTextForGroup(groupId, menu.statistics(), 20)
end

function menu.setup()
    tarmac.menu.forPlayers(function(player)
        local root = missionCommands.addSubMenuForGroup(player.groupId, "Industry")
        missionCommands.addCommandForGroup(player.groupId, "Get current statistics", root, showStatistics, player.groupId)
        return root
    end)
end

return menu
end

-- module industry.stranded (industry/stranded.lua)
__modules["industry.stranded"] = function(...)
--- Stranded aircraft. A damaged AI aircraft that ends up on the ground
-- without crashing (an emergency landing in a field, a damaged helicopter
-- that set down, a wreck left on a runway) raises no further event. DCS
-- still counts it as alive, so its group would never respawn. Every
-- respawn.deadCheckInterval seconds the aircraft of respawn groups are
-- checked: one that is damaged, on the ground and not moving at two checks
-- in a row is removed and counts as lost. Object.destroy does not always
-- remove a damaged aircraft, so one that is still there at the next check
-- is blown up.

local tarmac = require("tarmac")
local respawn = require("industry.respawn")

local log = tarmac.log.new("industry.stranded")
local db, tracker, object = tarmac.db, tarmac.tracker, tarmac.object

local stranded = {}

-- below this speed in m/s an aircraft counts as not moving
local STILL_SPEED = 1

local damaged = {}  -- [unitName] = true after a hit or an aborted mission
local suspects = {} -- [unitName] = true when found stranded at the last check
local removed = {}  -- [unitName] = unit removed at the last check

local function speed(unit)
    local velocity = object.call(unit, "getVelocity")
    if velocity == nil then
        return nil
    end
    return math.sqrt(velocity.x * velocity.x + velocity.y * velocity.y + velocity.z * velocity.z)
end

local function isDamaged(unit, unitName)
    if damaged[unitName] then
        return true
    end
    local life, life0 = object.life(unit), object.call(unit, "getLife0")
    return life ~= nil and life0 ~= nil and life < life0
end

--- True for an AI aircraft that is damaged, on the ground and not moving.
function stranded.isStranded(unit)
    local unitName = object.name(unit)
    if unitName == nil or not object.isAircraft(unit) or object.playerName(unit) ~= nil then
        return false
    end
    if object.call(unit, "isActive") == false or object.call(unit, "inAir") ~= false then
        return false
    end
    local current = speed(unit)
    return current ~= nil and current < STILL_SPEED and isDamaged(unit, unitName)
end

local function blowUpLeftovers()
    for unitName, unit in pairs(removed) do
        local point = object.exists(unit) and object.point(unit)
        if point then
            trigger.action.explosion(point, 400)
            log:info("%s was not removed, blown up", unitName)
        end
    end
    removed = {}
end

--- One check of all aircraft of respawn groups.
function stranded.check()
    blowUpLeftovers()
    local found = {}
    for _, groupName in ipairs(respawn.groups()) do
        local record = db.group(groupName)
        if record and (record.category == "plane" or record.category == "helicopter") then
            for _, unitName in ipairs(tracker.aliveUnits(groupName)) do
                local unit = Unit.getByName(unitName)
                if unit and stranded.isStranded(unit) then
                    if suspects[unitName] then
                        log:info("%s is damaged and has not moved on the ground since the last check, removed", unitName)
                        removed[unitName] = unit
                        tracker.destroyUnit(unit)
                    else
                        found[unitName] = true
                    end
                end
            end
        end
    end
    suspects = found
end

local function markDamaged(unit)
    local unitName = object.name(unit)
    if unitName and object.isAircraft(unit) then
        damaged[unitName] = true
    end
end

function stranded.setup(configuration)
    if not configuration.respawn.removeStranded then
        return
    end
    tarmac.events.on("HIT", function(event)
        markDamaged(event.target)
    end)
    tarmac.events.on("AI_ABORT_MISSION", function(event)
        markDamaged(event.initiator)
    end)
    -- a respawned unit reuses the name of the old one
    tarmac.events.on("BIRTH", function(event)
        local unitName = object.name(event.initiator)
        if unitName then
            damaged[unitName] = nil
            suspects[unitName] = nil
        end
    end)
    local interval = configuration.respawn.deadCheckInterval
    tarmac.scheduler.every(interval, stranded.check, { delay = interval + 8, name = "industry.stranded" })
end

return stranded
end

-- module industry (industry/init.lua)
__modules["industry"] = function(...)
--- Industry Wars - resource management, respawns and tickets for DCS World.
--
-- Load dist/industry.lua with DO SCRIPT FILE, then configure and start it
-- from the mission (e.g. an init.lua loaded right after it):
--   industry.setup({
--       startResources = 800,
--       respawn = { groups = { ["RedCAP-1"] = 400, ["TankPlatoonRed-1"] = {} } },
--   })
-- See README.md for all options and the mission editor conventions.

local existing = rawget(_G, "industry")
if existing ~= nil then
    env.warning("[industry] Industry is already loaded, the second copy is ignored", false)
    return existing
end

local tarmac = require("tarmac")
local config = require("industry.config")
local tickets = require("industry.tickets")
local economy = require("industry.economy")
local objectives = require("industry.objectives")
local production = require("industry.production")
local respawn = require("industry.respawn")
local logistics = require("industry.logistics")
local airfield = require("industry.airfield")
local csar = require("industry.csar")
local losses = require("industry.losses")
local menu = require("industry.menu")
local stranded = require("industry.stranded")

local log = tarmac.log.new("industry")

local industry = {
    version = "2.0.0-dev",
    tarmac = tarmac,
    tickets = tickets,
    economy = economy,
    objectives = objectives,
    production = production,
    respawn = respawn,
    logistics = logistics,
    csar = csar,
    menu = menu,
    stranded = stranded,
}

local started = false

--- Starts Industry with the mission's configuration table.
function industry.setup(given)
    if started then
        log:warn("industry.setup() called more than once, ignored")
        return industry
    end
    started = true
    local cfg = config.build(given)
    industry.config = cfg

    tickets.setup(cfg)
    objectives.setup(cfg)
    local storages = {}
    for _, coalitionId in ipairs(tarmac.side.BOTH) do
        storages[coalitionId] = objectives.count(coalitionId, "storage")
    end
    economy.setup(cfg, storages)
    production.setup(cfg)
    respawn.setup(cfg)
    stranded.setup(cfg)
    logistics.setup(cfg)
    airfield.setup(cfg)
    csar.setup(cfg)
    losses.setup(cfg)
    menu.setup()

    log:info("Industry %s started (Tarmac %s)", industry.version, tarmac.version)
    return industry
end

--- Called by the waypoint action that Industry adds to convoy routes.
function industry.convoyArrived(groupName)
    return logistics.convoyArrived(groupName)
end

--- Adds resources to a coalition ("red", "blue", 1 or 2).
function industry.addResources(coalitionId, tons, reason)
    return economy.add(coalitionId, tons, reason or "script")
end

--- Registers a group for respawn after setup (cost optional).
function industry.addRespawnGroup(groupName, cost)
    return respawn.register(groupName, cost)
end

--- Queues a group for respawn (cost optional, 0 = free).
function industry.queueRespawn(groupName, cost)
    return respawn.queue(groupName, cost)
end

_G.industry = industry

tarmac.scheduler.after(10, function()
    if not started then
        log:error("industry.setup() was not called, Industry is not running")
        trigger.action.outText("Industry is loaded but industry.setup() was not called", 30)
    end
end)

log:info("Industry %s loaded", industry.version)

return industry
end

require("industry")
end
